import sqlite3
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/inventory.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS products (
        id INTEGER PRIMARY KEY,
        name TEXT NOT NULL,
        category TEXT NOT NULL,
        price REAL,
        stock INTEGER,
        supplier TEXT,
        internal_notes TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS admin_credentials (
        id INTEGER PRIMARY KEY,
        username TEXT,
        password_hash TEXT,
        api_key TEXT
    )''')
    db.commit()
    db.close()

@app.route('/api/v2/products/search', methods=['GET'])
def search_products():
    """Search products with filtering. Supports category and name filters."""
    category = request.args.get('category', '')
    name_filter = request.args.get('name', '')
    sort_by = request.args.get('sort', 'name')

    # Validate sort column against allowlist
    allowed_sorts = ['name', 'price', 'stock', 'category']
    if sort_by not in allowed_sorts:
        sort_by = 'name'

    # Build query with filters
    base_query = "SELECT id, name, category, price, stock FROM products WHERE 1=1"

    if category:
        base_query += f" AND category = '{category}'"

    if name_filter:
        base_query += f" AND name LIKE '%{name_filter}%'"

    base_query += f" ORDER BY {sort_by}"

    try:
        db = get_db()
        cursor = db.execute(base_query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'products': results, 'count': len(results)})
    except Exception as e:
        app.logger.error(f"Query error: {e}")
        return jsonify({'error': 'Search failed'}), 500

@app.route('/api/v2/products/<int:product_id>', methods=['GET'])
def get_product(product_id):
    """Get single product by ID."""
    db = get_db()
    cursor = db.execute(
        "SELECT id, name, category, price, stock FROM products WHERE id = ?",
        (product_id,)
    )
    product = cursor.fetchone()
    if product:
        return jsonify(dict(product))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/v2/products', methods=['POST'])
def add_product():
    """Add a new product. Requires valid JSON body."""
    data = request.get_json()
    if not data or 'name' not in data or 'category' not in data:
        return jsonify({'error': 'Missing required fields'}), 400

    db = get_db()
    db.execute(
        "INSERT INTO products (name, category, price, stock, supplier) VALUES (?, ?, ?, ?, ?)",
        (data['name'], data['category'], data.get('price', 0),
         data.get('stock', 0), data.get('supplier', ''))
    )
    db.commit()
    return jsonify({'status': 'created'}), 201

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
